+func (c *contextCheckpointRecorder) RecordContext(ctx context.Context, rc planner.RunContext, step planner.Step) error {
+	c.count++
+	if c.mu != nil {
+		if !c.mu.TryRLock() {
+			c.t.Error("context persistence held inspection lock")
+		} else {
+			c.mu.RUnlock()
+		}
+	}
